action.query:
query Query($where: WorkOrderProcessDistributionGroupWhereInput, $orderBy: [WorkOrderProcessDistributionGroupOrderByInput!], $first: Int, $after: String) {
  workOrderProcessDistributionGroup(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        averageRate
        cycleTime
        distributionUnloadPercent
        estimatedTime
        idealRate
        percentComplete
        producedQuantity
        productionOperators
        quotedRate
        requiredQuantity
        scrappedQuantity
        setupOperators
        setupRate
        standardRate
        allowDistributionUnload
        bottleneck
        locked
        requireParallelOutput
        singleSetupRate
        groupId
        actualFinishAt
        actualStartAt
        earliestStartAt
        latestStartAt
        scheduledFinishAt
        scheduledStartAt
        customData
        workOrderProcessDistributionStatus {
          id
          name
        }

        calendarEvent {
          id
          title
        }
        schedulingGroup {
          id
          name
        }
        workcenter {
          id
          code
        }
      }
    }
  }
}
